-- CLASS_MIGRATION_SCOPE: runtime
-- CLASS_INTEGRATION_STRICT: class:paladin
-- CLASS_WORK_STATUS: paladin:complete-roster=READY_V3
begin;

alter table public.spell_catalog drop constraint if exists spell_catalog_source_kind_check;
alter table public.spell_catalog
  add constraint spell_catalog_source_kind_check
  check (source_kind = any(array['srd'::text,'official'::text,'third_party'::text]));

insert into public.spell_catalog(
  slug,name_en,name_ru,spell_level,school,casting_time,spell_range,area,duration,components,
  concentration,ritual,check_type,damage,effect_summary,upcast,source,source_kind,license,
  author_description,author_comment,roll_mode
) values
    ('armor-of-agathys','Armor of Agathys','Доспех Агатиса',1,'Abjuration','Действие','На себя','','1 час',ARRAY['В','С','М']::text[],false,false,'','5 холодом','Вы получаете 5 временных HP. Пока эти временные HP сохраняются, существо, попавшее по вам рукопашной атакой, получает 5 урона холодом.','+5 временных HP и +5 урона холодом за каждый уровень ячейки выше 1.','Книга игрока','official','PROPRIETARY','','','contextual'),
    ('arms-of-hadar','Arms of Hadar','Руки Хадара',1,'Conjuration','Действие','На себя','Радиус 10 футов','Мгновенно',ARRAY['В','С']::text[],false,false,'Спасбросок Силы','2d6 некротического','Существа в радиусе 10 футов совершают спасбросок Силы. При провале получают 2d6 некротического урона и не могут использовать Реакции до своего следующего хода; при успехе получают половину урона.','+1d6 урона за каждый уровень ячейки выше 1.','Книга игрока','official','PROPRIETARY','','','contextual'),
    ('compelled-duel','Compelled Duel','Вынужденная дуэль',1,'Enchantment','Бонусное действие','30 футов','','Концентрация, до 1 минуты',ARRAY['В']::text[],true,false,'Спасбросок Мудрости','','При провале спасброска цель получает Помеху на атаки против других существ и должна преодолевать спасбросок Мудрости, пытаясь добровольно удалиться дальше 30 футов от вас.','','Книга игрока','official','PROPRIETARY','','','contextual'),
    ('crown-of-madness','Crown of Madness','Корона безумия',2,'Enchantment','Действие','120 футов','','Концентрация, до 1 минуты',ARRAY['В','С']::text[],true,false,'Спасбросок Мудрости','','Гуманоид при провале спасброска Очарован. Пока эффект поддерживается, вы можете заставлять его использовать действие для рукопашной атаки выбранной вами цели, если подходящая цель находится в пределах досягаемости.','','Книга игрока','official','PROPRIETARY','','','contextual'),
    ('flash-fever','Flash Fever','Вспышка лихорадки',3,'Necromancy','Действие','60 футов','','Концентрация, до 1 минуты',ARRAY['В','С','М']::text[],true,false,'Спасбросок Телосложения','Нарастающий огненный урон','Живое существо при провале спасброска заболевает лихорадкой. В начале его следующего хода получает 1d6 огненного урона; последующие срабатывания увеличиваются ещё на 1d6. Цель может действием повторять спасбросок и завершить эффект.','Начальный урон увеличивается на 1d6 за каждый уровень ячейки выше 3.','Сторонний источник: Мрачная Пустошь','third_party','PROPRIETARY','','','contextual')
on conflict(slug) do update set
  name_ru=excluded.name_ru,
  spell_level=excluded.spell_level,
  school=excluded.school,
  casting_time=excluded.casting_time,
  spell_range=excluded.spell_range,
  area=excluded.area,
  duration=excluded.duration,
  components=excluded.components,
  concentration=excluded.concentration,
  ritual=excluded.ritual,
  check_type=excluded.check_type,
  damage=excluded.damage,
  effect_summary=excluded.effect_summary,
  upcast=excluded.upcast,
  source=excluded.source,
  source_kind=excluded.source_kind,
  license=excluded.license,
  author_description=excluded.author_description,
  author_comment=excluded.author_comment,
  roll_mode=excluded.roll_mode,
  updated_at=now();

create or replace function private.paladin_extended_upsert_oath_v3(
  p_campaign_id uuid,
  p_catalog_key text,
  p_slug text,
  p_name text,
  p_summary text,
  p_source_kind text,
  p_source_label text
) returns uuid
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_parent uuid;
  v_id uuid;
begin
  select id into v_parent
  from public.rule_templates
  where campaign_id=p_campaign_id and kind='class' and catalog_key='class:paladin' and is_active
  order by version desc,created_at desc limit 1;
  if v_parent is null then raise exception 'PALADIN_EXTENDED_PARENT_NOT_FOUND:%',p_campaign_id; end if;

  select id into v_id
  from public.rule_templates
  where campaign_id=p_campaign_id and kind='subclass' and catalog_key=p_catalog_key
  order by is_active desc,version desc,created_at desc limit 1;

  if v_id is null then
    insert into public.rule_templates(
      campaign_id,kind,slug,name,description,version,mechanics,choices,is_active,parent_template_id,unlock_level,
      catalog_key,catalog_revision,source_kind,source_label,is_builtin,mechanical_summary,author_description,author_comment,rules_meta
    ) values (
      p_campaign_id,'subclass',p_slug,p_name,p_summary,1,'[]'::jsonb,'[]'::jsonb,true,v_parent,3,
      p_catalog_key,'paladin-complete-15-oaths-v3',p_source_kind,p_source_label,true,p_summary,
      p_summary,
      'Клятва сохранена в существующем русском литературном пакете Паладина; эта запись подключает её правила к движку персонажа.',
      jsonb_build_object(
        'class_key','paladin','parent_catalog_key','class:paladin','runtime_stage',5,
        'runtime_revision','paladin-complete-15-oaths-v3','mechanics_status','READY',
        'spellcasting_ability','charisma','oath_spells_always_prepared',true,
        'player_facing_language','ru','translation_preserved',true
      )
    ) returning id into v_id;
  else
    update public.rule_templates set
      slug=p_slug,name=p_name,
      description=case when btrim(coalesce(description,''))='' then p_summary else description end,
      parent_template_id=v_parent,unlock_level=3,is_active=true,is_builtin=true,
      catalog_revision='paladin-complete-15-oaths-v3',
      source_kind=p_source_kind,source_label=p_source_label,
      mechanical_summary=case when btrim(coalesce(mechanical_summary,''))='' then p_summary else mechanical_summary end,
      rules_meta=coalesce(rules_meta,'{}'::jsonb)||jsonb_build_object(
        'class_key','paladin','parent_catalog_key','class:paladin','runtime_stage',5,
        'runtime_revision','paladin-complete-15-oaths-v3','mechanics_status','READY',
        'spellcasting_ability','charisma','oath_spells_always_prepared',true,
        'player_facing_language','ru','translation_preserved',true
      ),
      updated_at=now()
    where id=v_id;
  end if;

  update public.rule_templates set is_active=false,updated_at=now()
  where campaign_id=p_campaign_id and kind='subclass' and catalog_key=p_catalog_key and id<>v_id and is_active;

  return v_id;
end;
$function$;

revoke all on function private.paladin_extended_upsert_oath_v3(uuid,text,text,text,text,text,text) from public,anon,authenticated;
grant execute on function private.paladin_extended_upsert_oath_v3(uuid,text,text,text,text,text,text) to service_role;

create or replace function private.paladin_extended_set_level_v3(
  p_template_id uuid,
  p_level integer,
  p_feature_mechanics jsonb,
  p_spell_slugs text[],
  p_source_key text
) returns void
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_mechanics jsonb:=coalesce(p_feature_mechanics,'[]'::jsonb);
  v_slug text;
begin
  foreach v_slug in array coalesce(p_spell_slugs,array[]::text[]) loop
    v_mechanics:=v_mechanics||jsonb_build_array(private.paladin_stage4_spell_mechanic_v2(v_slug,p_source_key));
  end loop;

  insert into public.rule_template_levels(template_id,level,mechanics,choices)
  values(p_template_id,p_level,v_mechanics,'[]'::jsonb)
  on conflict(template_id,level) do update set mechanics=excluded.mechanics,choices=excluded.choices;
end;
$function$;

revoke all on function private.paladin_extended_set_level_v3(uuid,integer,jsonb,text[],text) from public,anon,authenticated;
grant execute on function private.paladin_extended_set_level_v3(uuid,integer,jsonb,text[],text) to service_role;

create or replace function private.ensure_paladin_extended_oaths_v3(p_campaign_id uuid)
returns void
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_id uuid;
  v_source_key text;
begin
  perform private.ensure_paladin_phb2024_subclasses_stage4_v2(p_campaign_id);

  v_id := private.paladin_extended_upsert_oath_v3(p_campaign_id,'subclass:paladin:conquest','paladin-oath-conquest','Клятва Завоевания','Подчиняет врагов страхом, ломает их движение и превращает давление ближнего боя в оружие.','official','Ксанатар: руководство обо всём');
  v_source_key := 'conquest-oath-spells';
  perform private.paladin_extended_set_level_v3(v_id,3,$json$[{"id":"conquest-presence-feature","type":"grant","sourceKey":"conquering-presence","target":"feature","key":"class:paladin:conquest:conquering-presence","payload":{"label":"Покоряющее присутствие","description":"Действием тратит Божественное проведение: выбранные существа в 30 футах спасаются Мудростью или Испуганы на 1 минуту, повторяя спасбросок в конце хода.","runtime":{"kind":"channel_divinity_feature","economy":"action","rangeFeet":30,"saveAbility":"wisdom","condition":"frightened","durationMinutes":1,"repeatSave":"end_of_turn"}}},{"id":"conquest-presence-action","type":"action","sourceKey":"conquering-presence","key":"conquering_presence","label":"Покоряющее присутствие","economy":"action","tags":["класс","семантика"],"effects":[{"key":"conquering_presence","kind":"semantic","payload":{"rangeFeet":30,"targets":"chosen_creatures","saveAbility":"wisdom","condition":"frightened","durationMinutes":1,"repeatSave":"end_of_turn"}}],"resourceKey":"channel_divinity","resourceCost":1},{"id":"conquest-guided-strike-feature","type":"grant","sourceKey":"guided-strike","target":"feature","key":"class:paladin:conquest:guided-strike","payload":{"label":"Направленный удар","description":"После броска атаки, но до объявления результата, можно потратить Божественное проведение и добавить +10 к броску.","runtime":{"kind":"channel_divinity_feature","trigger":"after_attack_roll_before_result","attackRollBonus":10}}},{"id":"conquest-guided-strike-action","type":"action","sourceKey":"guided-strike","key":"guided_strike","label":"Направленный удар","economy":"triggered","tags":["класс","семантика"],"effects":[{"key":"guided_strike","kind":"semantic","payload":{"trigger":"after_attack_roll_before_result","attackRollBonus":10}}],"resourceKey":"channel_divinity","resourceCost":1}]$json$::jsonb,ARRAY['armor-of-agathys','command']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,5,$json$[]$json$::jsonb,ARRAY['hold-person','spiritual-weapon']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,7,$json$[{"id":"conquest-aura-feature","type":"grant","sourceKey":"aura-of-conquest","target":"feature","key":"class:paladin:conquest:aura","payload":{"label":"Аура завоевания","description":"Испуганные вами враги в Ауре защиты имеют Скорость 0 и в начале хода получают психический урон, равный половине уровня Паладина.","runtime":{"kind":"aura_extension","auraKey":"aura_of_protection","requiresCondition":"frightened_by_you","targetSpeed":0,"startTurnPsychicDamage":"floor(paladin_level / 2)"}}}]$json$::jsonb,ARRAY[]::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,9,$json$[]$json$::jsonb,ARRAY['bestow-curse','fear']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,13,$json$[]$json$::jsonb,ARRAY['dominate-beast','stoneskin']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,15,$json$[{"id":"conquest-scornful-rebuke-feature","type":"grant","sourceKey":"scornful-rebuke","target":"feature","key":"class:paladin:conquest:scornful-rebuke","payload":{"label":"Презрительный отпор","description":"Существо, попавшее по вам рукопашной атакой, получает психический урон, равный вашему модификатору Харизмы.","runtime":{"kind":"passive_damage","trigger":"hit_by_melee_attack","damage":"charisma_modifier","damageType":"psychic"}}}]$json$::jsonb,ARRAY[]::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,17,$json$[]$json$::jsonb,ARRAY['cloudkill','dominate-person']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,20,$json$[{"id":"conquest-invincible-conqueror-resource","type":"resource","sourceKey":"conquest-invincible-conqueror","grantOperation":"REPLACE","priority":20,"key":"conquest_invincible_conqueror","label":"Непобедимый завоеватель","max":1,"initial":"full","restore":"full","recharge":["long_rest"],"recoveryRules":[{"trigger":"long_rest","restore":"full"}]},{"id":"conquest-invincible-conqueror-feature","type":"grant","sourceKey":"invincible-conqueror","target":"feature","key":"class:paladin:conquest:invincible-conqueror","payload":{"label":"Непобедимый завоеватель","description":"Действием на 1 минуту получает сопротивление всему урону, дополнительную атаку действием Атака и критические попадания на 19–20.","runtime":{"kind":"transformation","durationMinutes":1,"resistance":"all","extraAttack":1,"criticalRange":[19,20]}}},{"id":"conquest-invincible-conqueror-action","type":"action","sourceKey":"invincible-conqueror","key":"invincible_conqueror","label":"Непобедимый завоеватель","economy":"action","tags":["класс","семантика"],"effects":[{"key":"invincible_conqueror","kind":"semantic","payload":{"durationMinutes":1,"resistance":"all","extraAttack":1,"criticalRange":[19,20]}}],"resourceKey":"conquest_invincible_conqueror","resourceCost":1}]$json$::jsonb,ARRAY[]::text[],v_source_key);
  perform private.sync_rule_template_spell_links(v_id);

  v_id := private.paladin_extended_upsert_oath_v3(p_campaign_id,'subclass:paladin:redemption','paladin-oath-redemption','Клятва Искупления','Гасит конфликт словом, принимает чужой урон и наказывает тех, кто продолжает насилие.','official','Ксанатар: руководство обо всём');
  v_source_key := 'redemption-oath-spells';
  perform private.paladin_extended_set_level_v3(v_id,3,$json$[{"id":"redemption-emissary-feature","type":"grant","sourceKey":"emissary-of-peace","target":"feature","key":"class:paladin:redemption:emissary","payload":{"label":"Посланник мира","description":"Бонусным действием тратит Божественное проведение и на 10 минут получает +5 к проверкам Убеждения.","runtime":{"kind":"channel_divinity_feature","economy":"bonus_action","durationMinutes":10,"persuasionBonus":5}}},{"id":"redemption-emissary-action","type":"action","sourceKey":"emissary-of-peace","key":"emissary_of_peace","label":"Посланник мира","economy":"bonus_action","tags":["класс","семантика"],"effects":[{"key":"emissary_of_peace","kind":"semantic","payload":{"durationMinutes":10,"persuasionBonus":5}}],"resourceKey":"channel_divinity","resourceCost":1},{"id":"redemption-rebuke-feature","type":"grant","sourceKey":"rebuke-the-violent","target":"feature","key":"class:paladin:redemption:rebuke","payload":{"label":"Упрёк жестокому","description":"Реакцией после того, как враг в 30 футах наносит урон другому существу, тратит Божественное проведение: нападающий спасается Мудростью и получает сияющий урон, равный нанесённому, либо половину при успехе.","runtime":{"kind":"channel_divinity_feature","economy":"reaction","rangeFeet":30,"saveAbility":"wisdom","damage":"triggering_damage","damageType":"radiant","onSuccess":"half"}}},{"id":"redemption-rebuke-action","type":"action","sourceKey":"rebuke-the-violent","key":"rebuke_the_violent","label":"Упрёк жестокому","economy":"reaction","tags":["класс","семантика"],"effects":[{"key":"rebuke_the_violent","kind":"semantic","payload":{"trigger":"visible_enemy_damages_other_creature","rangeFeet":30,"saveAbility":"wisdom","damage":"triggering_damage","damageType":"radiant","onSuccess":"half"}}],"resourceKey":"channel_divinity","resourceCost":1}]$json$::jsonb,ARRAY['sanctuary','sleep']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,5,$json$[]$json$::jsonb,ARRAY['calm-emotions','hold-person']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,7,$json$[{"id":"redemption-guardian-aura-feature","type":"grant","sourceKey":"aura-of-guardian","target":"feature","key":"class:paladin:redemption:guardian-aura","payload":{"label":"Аура хранителя","description":"Реакцией принимает на себя урон, который должно получить другое существо в Ауре защиты. Этот переносимый урон нельзя уменьшить или предотвратить.","runtime":{"kind":"aura_reaction","auraKey":"aura_of_protection","trigger":"ally_takes_damage","transferDamageToSelf":true,"damageCannotBeReduced":true}}}]$json$::jsonb,ARRAY[]::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,9,$json$[]$json$::jsonb,ARRAY['counterspell','hypnotic-pattern']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,13,$json$[]$json$::jsonb,ARRAY['resilient-sphere','stoneskin']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,15,$json$[{"id":"redemption-protective-spirit-feature","type":"grant","sourceKey":"protective-spirit","target":"feature","key":"class:paladin:redemption:protective-spirit","payload":{"label":"Защитный дух","description":"Если в конце хода у вас меньше половины максимума HP, но больше 0, вы восстанавливаете 1d6 + половина уровня Паладина HP.","runtime":{"kind":"passive_healing","trigger":"end_of_turn","condition":"0 < hp < half_max","healing":"1d6 + floor(paladin_level / 2)"}}}]$json$::jsonb,ARRAY[]::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,17,$json$[]$json$::jsonb,ARRAY['hold-monster','wall-of-force']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,20,$json$[{"id":"redemption-emissary-redemption-feature","type":"grant","sourceKey":"emissary-of-redemption","target":"feature","key":"class:paladin:redemption:emissary-redemption","payload":{"label":"Посланник искупления","description":"Получаете сопротивление урону от других существ и возвращаете нападающему сияющий урон, равный половине полученного; против конкретного существа защита прекращается до долгого отдыха после вашей агрессии против него.","runtime":{"kind":"passive_defense","resistance":"damage_from_other_creatures","reflectRadiant":"half_damage_taken","breaksAgainstCreatureOn":"attack_damage_or_harmful_spell_until_long_rest"}}}]$json$::jsonb,ARRAY[]::text[],v_source_key);
  perform private.sync_rule_template_spell_links(v_id);

  v_id := private.paladin_extended_upsert_oath_v3(p_campaign_id,'subclass:paladin:watchers','paladin-oath-watchers','Клятва Стражей','Охраняет границу миров, усиливает волю отряда и изгоняет чужеродных существ.','official','Таша: котёл всякой всячины');
  v_source_key := 'watchers-oath-spells';
  perform private.paladin_extended_set_level_v3(v_id,3,$json$[{"id":"watchers-will-feature","type":"grant","sourceKey":"watchers-will","target":"feature","key":"class:paladin:watchers:will","payload":{"label":"Воля Стража","description":"Действием тратит Божественное проведение: выбранные существа в 30 футах числом до модификатора Харизмы получают на 1 минуту преимущество на спасброски Интеллекта, Мудрости и Харизмы.","runtime":{"kind":"channel_divinity_feature","economy":"action","rangeFeet":30,"targetCount":"max(1,charisma_modifier)","durationMinutes":1,"saveAdvantages":["intelligence","wisdom","charisma"]}}},{"id":"watchers-will-action","type":"action","sourceKey":"watchers-will","key":"watchers_will","label":"Воля Стража","economy":"action","tags":["класс","семантика"],"effects":[{"key":"watchers_will","kind":"semantic","payload":{"rangeFeet":30,"targetCount":"max(1,charisma_modifier)","durationMinutes":1,"saveAdvantages":["intelligence","wisdom","charisma"]}}],"resourceKey":"channel_divinity","resourceCost":1},{"id":"watchers-abjure-feature","type":"grant","sourceKey":"abjure-extraplanar","target":"feature","key":"class:paladin:watchers:abjure","payload":{"label":"Изгнание иномерного","description":"Действием тратит Божественное проведение: выбранные Аберрации, Небожители, Элементали, Феи и Исчадия в 30 футах спасаются Мудростью или Изгнаны на 1 минуту.","runtime":{"kind":"channel_divinity_feature","economy":"action","rangeFeet":30,"types":["aberration","celestial","elemental","fey","fiend"],"saveAbility":"wisdom","condition":"turned","durationMinutes":1}}},{"id":"watchers-abjure-action","type":"action","sourceKey":"abjure-extraplanar","key":"abjure_extraplanar","label":"Изгнание иномерного","economy":"action","tags":["класс","семантика"],"effects":[{"key":"abjure_extraplanar","kind":"semantic","payload":{"rangeFeet":30,"types":["aberration","celestial","elemental","fey","fiend"],"saveAbility":"wisdom","condition":"turned","durationMinutes":1}}],"resourceKey":"channel_divinity","resourceCost":1}]$json$::jsonb,ARRAY['alarm','detect-magic']::text[],v_source_key);
