"семантика"],"effects":[{"key":"infernal_mass_seals","kind":"semantic","payload":{"rangeFeet":30,"effect":"place_seals_on_multiple_targets"}}],"resourceKey":"channel_divinity","resourceCost":1},{"id":"infernal-command-feature","type":"grant","sourceKey":"invoke-hell-command","target":"feature","key":"class:paladin:illrigger:command","payload":{"label":"Адский приказ","description":"Тратит Божественное проведение и приказывает отмеченной печатью цели выполнить краткий приказ; цель спасается Мудростью против Сл Паладина.","runtime":{"kind":"channel_divinity_feature","economy":"action","requires":"target_has_your_seal","saveAbility":"wisdom","effect":"brief_command"}}},{"id":"infernal-command-action","type":"action","sourceKey":"invoke-hell-command","key":"infernal_command","label":"Адский приказ","economy":"action","tags":["класс","семантика"],"effects":[{"key":"infernal_command","kind":"semantic","payload":{"requires":"target_has_your_seal","saveAbility":"wisdom","effect":"brief_command"}}],"resourceKey":"channel_divinity","resourceCost":1}]$json$::jsonb,ARRAY['command','hellish-rebuke']::text[],v_source_key);
  perform private.paladin_extended_set_level_v3(v_id,5,$json$[]$json$::jsonb,ARRAY['darkness','suggestion']::text[],v_source_key);
