$function$;

revoke all on function private.ensure_paladin_extended_oaths_v3(uuid) from public,anon,authenticated;
grant execute on function private.ensure_paladin_extended_oaths_v3(uuid) to service_role;

drop trigger if exists aaaaaaaag_campaigns_certify_paladin_runtime_final_v1 on public.campaigns;
drop trigger if exists aaaaaaaah_campaigns_certify_paladin_runtime_final_v2 on public.campaigns;

create or replace function private.ensure_paladin_extended_oaths_v3_after_campaign()
returns trigger
language plpgsql
security definer
set search_path=''
as $function$
begin
  perform private.ensure_paladin_extended_oaths_v3(new.id);
  return new;
end;
$function$;

revoke all on function private.ensure_paladin_extended_oaths_v3_after_campaign() from public,anon,authenticated;

drop trigger if exists aaaaaaaai_campaigns_ensure_paladin_extended_oaths_v3 on public.campaigns;
create trigger aaaaaaaai_campaigns_ensure_paladin_extended_oaths_v3
after insert on public.campaigns
for each row execute function private.ensure_paladin_extended_oaths_v3_after_campaign();

do $block$
declare r record;
begin
  for r in select id from public.campaigns loop
    perform private.ensure_paladin_extended_oaths_v3(r.id);
  end loop;
end;
$block$;

commit;